Aevrynd::ReusableMemoryStats FrontierWorldGame::GetReusableMemoryStats()const{const ReusableMemoryStats scene=scene_.MemoryStats(),collision=collisionWorld_.MemoryStats(),streaming=worldStreamer_.MemoryStats(),navigation=navigationWorkspace_.MemoryStats();std::size_t retained=scene.retainedCapacityBytes+collision.retainedCapacityBytes+streaming.retainedCapacityBytes+navigation.retainedCapacityBytes+buildings_.capacity()*sizeof(Building)+monsters_.capacity()*sizeof(Monster),reclaimable=scene.reclaimableCapacityBytes+collision.reclaimableCapacityBytes+streaming.reclaimableCapacityBytes+navigation.reclaimableCapacityBytes;for(const Monster& monster:monsters_){retained+=monster.path.capacity()*sizeof(Vec3);if(monster.path.capacity()>monster.path.size())reclaimable+=(monster.path.capacity()-monster.path.size())*sizeof(Vec3);}auto excess=[](std::size_t capacity,std::size_t size,std::size_t baseline,std::size_t element){const std::size_t target=(std::max)(size,baseline);return capacity>target?(capacity-target)*element:std::size_t{};};reclaimable+=excess(buildings_.capacity(),buildings_.size(),32,sizeof(Building))+excess(monsters_.capacity(),monsters_.size(),64,sizeof(Monster));return{retained,reclaimable,lastReusableMemoryReleasedBytes_,reusableMemoryTrimCount_};}
std::size_t FrontierWorldGame::TrimReusableMemory(){const std::size_t before=GetReusableMemoryStats().retainedCapacityBytes;scene_.TrimUnusedMemory();collisionWorld_.TrimUnusedMemory();worldStreamer_.TrimUnusedMemory();navigationWorkspace_.TrimUnusedMemory(std::size_t(navigationGrid_.Settings().width)*navigationGrid_.Settings().depth);auto compact=[]<class T>(std::vector<T>& values,std::size_t baseline){std::vector<T> replacement;replacement.reserve((std::max)(values.size(),baseline));replacement.insert(replacement.end(),std::make_move_iterator(values.begin()),std::make_move_iterator(values.end()));values.swap(replacement);};for(Monster& monster:monsters_)compact(monster.path,monster.path.size());compact(buildings_,32);compact(monsters_,64);const std::size_t after=GetReusableMemoryStats().retainedCapacityBytes;lastReusableMemoryReleasedBytes_=before>after?before-after:0;++reusableMemoryTrimCount_;return lastReusableMemoryReleasedBytes_;}

