void FrontierWorldGame::AddEnvironment(){
    scene_.Mesh(terrainMesh_,{},MaterialVariant(groundMaterial_,{1,1,1,1},.085f,false));const float chunkSize=worldStreamer_.Settings().chunkSize,half=chunkSize*.5f;
    for(const WorldChunk3D& chunk:worldStreamer_.ResidentChunks()){
        uint32_t random=chunk.seed;const float back=chunk.center.z-half;
        for(int segment=0;segment<6;++segment){const float z=back+(float(segment)+.5f)*chunkSize/6.f,x=RiverCenter(z),nextX=RiverCenter(z+chunkSize/6.f),width=RiverWidth(z);if(std::abs(x-chunk.center.x)>half+width)continue;scene_.Mesh(boxMesh_,{{x,-2.05f,z},{0,std::atan2(nextX-x,chunkSize/6.f),0},{width*2.f,.16f,chunkSize/5.5f}},{{.035f,.19f,.27f,.88f},WaterSurface,false});}
        for(int index=0;index<8;++index){
            const float x=chunk.center.x+RandomRange(random,-half+2,half-2),z=chunk.center.z+RandomRange(random,-half+2,half-2),base=terrain_.SampleHeight(x,z),height=RandomRange(random,4.f,6.8f),crown=RandomRange(random,2.7f,4.3f);const bool nearWater=std::abs(x-RiverCenter(z))<RiverWidth(z)+4.f||Length(Vec2{x-40.f,z-72.f})<29.f;if(nearWater||Length(Vec2{x,z+2.f})<24.f||base<-1.f)continue;
            const Color trunk{.62f+RandomRange(random,0,.08f),.52f,.42f,1};scene_.Mesh(cylinderMesh_,{{x,base+height*.5f,z},{0,RandomRange(random,0,6.28f),0},{.48f,height,.48f}},MaterialVariant(barkMaterial_,trunk,1.2f));
            if(index%3){for(int tier=0;tier<3;++tier){const float tierScale=1.f-float(tier)*.2f;scene_.MeshLod(coneHighMesh_,coneLowMesh_,38,{{x,base+height*.72f+float(tier)*1.25f,z},{0,RandomRange(random,0,6.28f),0},{crown*tierScale,crown*.92f,crown*tierScale}},{{.035f+RandomRange(random,0,.02f),.18f+RandomRange(random,0,.07f),.065f,1},FoliageSurface});}}
            else for(int cluster=0;cluster<3;++cluster){const float angle=float(cluster)*2.094f;scene_.MeshLod(sphereHighMesh_,sphereLowMesh_,34,{{x+std::sin(angle)*crown*.22f,base+height+crown*.18f+float(cluster==0)*.5f,z+std::cos(angle)*crown*.22f},{0,angle,0},{crown*.72f,crown*.78f,crown*.72f}},{{.055f+RandomRange(random,0,.035f),.22f+RandomRange(random,0,.08f),.07f,1},FoliageSurface});}
        }
        for(int index=0;index<14;++index){const float x=chunk.center.x+RandomRange(random,-half+1,half-1),z=chunk.center.z+RandomRange(random,-half+1,half-1),base=terrain_.SampleHeight(x,z);if(base<-1.f||std::abs(x-RiverCenter(z))<RiverWidth(z)+2.f)continue;const float blade=RandomRange(random,.35f,.8f),yaw=RandomRange(random,0,6.28f);scene_.Mesh(boxMesh_,{{x,base+blade*.5f,z},{0,yaw,.08f},{.045f,blade,.32f}},{{.1f+RandomRange(random,0,.05f),.3f+RandomRange(random,0,.12f),.08f,1},FoliageSurface,false});scene_.Mesh(boxMesh_,{{x,base+blade*.5f,z},{0,yaw+1.57f,-.06f},{.045f,blade,.32f}},{{.08f,.26f+RandomRange(random,0,.1f),.06f,1},FoliageSurface,false});}
        for(int index=0;index<3;++index){const float x=chunk.center.x+RandomRange(random,-half+1,half-1),z=chunk.center.z+RandomRange(random,-half+1,half-1),scale=RandomRange(random,.7f,1.7f),base=terrain_.SampleHeight(x,z);if(base<-1.5f)continue;scene_.MeshLod(sphereHighMesh_,sphereLowMesh_,24,{{x,base+.3f,z},{RandomRange(random,0,.5f),RandomRange(random,0,6.28f),0},{scale,.62f,scale*.82f}},MaterialVariant(rockMaterial_,{.72f+RandomRange(random,0,.1f),.72f,.7f,1},.7f));}
    }
    if(worldStreamer_.Contains(ChunkAt({40,0,72},chunkSize)))scene_.Mesh(boxMesh_,{{40,-2.12f,72},{0,.08f,0},{46,.14f,34}},{{.035f,.23f,.33f,.9f},WaterSurface,false});
    auto addCabin=[&](Vec3 center,float yaw){if(!worldStreamer_.Contains(ChunkAt(center,chunkSize)))return;const float base=terrain_.SampleHeight(center.x,center.z);center.y=base;scene_.Mesh(boxMesh_,{center+Vec3{0,.28f,0},{0,yaw,0},{7.6f,.56f,6.4f}},MaterialVariant(rockMaterial_,{.78f,.76f,.72f,1},.35f));for(float side:{-1.f,1.f})scene_.Mesh(boxMesh_,{center+Vec3{side*3.45f,2.05f,0},{0,yaw,0},{.35f,3.55f,6.f}},MaterialVariant(woodMaterial_,{.76f,.66f,.52f,1},.48f));for(float side:{-1.f,1.f})scene_.Mesh(boxMesh_,{center+Vec3{0,2.05f,side*2.8f},{0,yaw,0},{7.2f,3.55f,.35f}},MaterialVariant(woodMaterial_,{.72f,.62f,.48f,1},.48f));for(float beam:{-2.8f,0.f,2.8f})scene_.Mesh(cylinderMesh_,{center+Vec3{beam,2.05f,2.98f},{0,0,1.57f},{.34f,3.6f,.34f}},MaterialVariant(barkMaterial_,{.55f,.43f,.32f,1},1.f));scene_.Mesh(boxMesh_,{center+Vec3{-1.8f,1.6f,3.02f},{0,yaw,0},{1.1f,2.45f,.18f}},MaterialVariant(woodMaterial_,{.48f,.38f,.28f,1},.6f));scene_.Mesh(boxMesh_,{center+Vec3{1.7f,1.9f,3.03f},{0,yaw,0},{1.25f,1.2f,.16f}},{{.22f,.58f,.72f,1},{.2f,.02f,.12f,1},false});scene_.Mesh(boxMesh_,{center+Vec3{0,4.15f,0},{0,yaw,.5f},{8.4f,.34f,3.8f}},MaterialVariant(woodMaterial_,{.58f,.45f,.35f,1},.42f));scene_.Mesh(boxMesh_,{center+Vec3{0,4.15f,0},{0,yaw,-.5f},{8.4f,.34f,3.8f}},MaterialVariant(woodMaterial_,{.62f,.48f,.36f,1},.42f));scene_.Mesh(boxMesh_,{center+Vec3{2.3f,5.f,-1.2f},{0,yaw,0},{.75f,2.4f,.75f}},MaterialVariant(rockMaterial_,{.72f,.7f,.67f,1},.5f));};
    addCabin({-12,0,17},.12f);addCabin({-38,0,-18},-.34f);addCabin({14,0,34},.42f);
    for(const Building& building:buildings_){if(!worldStreamer_.Contains(ChunkAt(building.position,chunkSize)))continue;if(building.kind==BuildingKind::Foundation)scene_.Mesh(boxMesh_,{building.position+Vec3{0,.2f,0},{0,building.yaw,0},{5,.4f,5}},MaterialVariant(rockMaterial_,{.76f,.74f,.7f,1},.38f));else if(building.kind==BuildingKind::Wall)scene_.Mesh(boxMesh_,{building.position+Vec3{0,1.5f,0},{0,building.yaw,0},{5,3,.35f}},MaterialVariant(woodMaterial_,{.75f,.63f,.48f,1},.5f));else{scene_.Mesh(boxMesh_,{building.position+Vec3{0,.15f,0},{0,0,.43f},{5.8f,.35f,3.2f}},MaterialVariant(woodMaterial_,{.58f,.45f,.34f,1},.42f));scene_.Mesh(boxMesh_,{building.position+Vec3{0,.15f,0},{0,0,-.43f},{5.8f,.35f,3.2f}},MaterialVariant(woodMaterial_,{.62f,.48f,.36f,1},.42f));}}
    if(viewMode_!=ViewMode::GodView){const Vec3 observer=controller_.Position();for(int cloud=0;cloud<5;++cloud){const float angle=float(cloud)*1.256f+automaticClock_*.003f;const Vec3 center=observer+Vec3{std::sin(angle)*85.f,42.f+float(cloud%2)*8.f,std::cos(angle)*85.f};for(int puff=0;puff<4;++puff)scene_.MeshLod(sphereHighMesh_,sphereLowMesh_,90,{center+Vec3{float(puff-1)*5.f,float(puff%2)*1.8f,float((puff*3)%5)-2.f},{0,angle,0},{12.f,4.2f,7.f}},{{.84f,.88f,.89f,.68f},{.94f,0,.2f,1},false});}}
}

